package com.libradesk.core;

import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import org.junit.jupiter.api.Test;

class CoreRandomizedTest {
 @Test void hashTableMatchesHashMapForRandomOperations(){HashTable<Integer,Integer> actual=new HashTable<>();Map<Integer,Integer> expected=new HashMap<>();Random r=new Random(8172);for(int i=0;i<100_000;i++){int k=r.nextInt(4000);if(r.nextBoolean()){int v=r.nextInt();assertEquals(expected.put(k,v),actual.put(k,v));}else assertEquals(expected.remove(k),actual.remove(k));assertEquals(expected.get(k),actual.get(k));}assertEquals(expected.size(),actual.size());}
 @Test void avlMatchesTreeMapForRandomOperations(){AvlTree<Integer> actual=new AvlTree<>();TreeMap<Integer,Integer> expected=new TreeMap<>();Random r=new Random(82);for(int i=0;i<100_000;i++){int k=r.nextInt(2000);if(r.nextBoolean()){actual.insert(k);expected.put(k,k);}else assertEquals(expected.remove(k)!=null,actual.delete(k));assertEquals(expected.size(),actual.size());}assertEquals(new ArrayList<>(expected.keySet()),actual.page(0,Integer.MAX_VALUE));}
 @Test void mergeSortMatchesArraysSort(){Random r=new Random(4);for(int run=0;run<100;run++){Integer[] a=new Integer[r.nextInt(1000)],b;for(int i=0;i<a.length;i++)a[i]=r.nextInt(100);b=a.clone();MergeSort.sort(a,Integer::compare);Arrays.sort(b);assertArrayEquals(b,a);}}
 @Test void quickSortAndBinarySearchMatchJdkBaselines(){Random r=new Random(41);for(int run=0;run<100;run++){Integer[] a=new Integer[r.nextInt(1000)];for(int i=0;i<a.length;i++)a[i]=r.nextInt(100);Integer[] baseline=a.clone();QuickSort.sort(a,Integer::compare);Arrays.sort(baseline);assertArrayEquals(baseline,a);if(a.length>0){int key=a[r.nextInt(a.length)],found=BinarySearch.exact(a,key,Integer::compare),lower=BinarySearch.lowerBound(a,key,Integer::compare);assertTrue(found>=0);assertEquals(key,a[found]);assertEquals(key,a[lower]);assertTrue(Arrays.binarySearch(a,key)>=0);}}}
 @Test void indexedHeapMatchesPriorityQueue(){IndexedMinHeap<Integer,Integer> actual=new IndexedMinHeap<>(Integer::compare);Map<Integer,Integer> items=new HashMap<>();PriorityQueue<Integer> baseline=new PriorityQueue<>();Random r=new Random(8);for(int i=0;i<100_000;i++){int key=r.nextInt(500);if(r.nextBoolean()){int val=r.nextInt(10000);Integer old=items.put(key,val);if(old!=null)baseline.remove(old);baseline.add(val);actual.put(key,val);}else{Integer old=items.remove(key);assertEquals(old,actual.remove(key));if(old!=null)baseline.remove(old);}assertEquals(baseline.peek(),actual.peek());}}
 @Test void trieUnicodePrefixAndTopK(){Trie t=new Trie();t.insert("Algorithms",10);t.insert("Algebra",4);t.insert("Álgebra",7);assertTrue(t.startsWith("alg"));assertEquals("algorithms",t.topK("alg",1).get(0));assertTrue(t.remove("Algorithms"));assertFalse(t.topK("alg",10).contains("algorithms"));}
 @Test void trieMatchesStreamFilterAcrossRandomOperations(){Trie actual=new Trie();Map<String,Integer> expected=new HashMap<>();Random r=new Random(551);for(int i=0;i<100_000;i++){String word="book"+r.nextInt(5000);if(r.nextBoolean()){int popularity=r.nextInt(1000);actual.insert(word,popularity);expected.put(word,popularity);}else{assertEquals(expected.remove(word)!=null,actual.remove(word));}if(i%100==0){String prefix="book"+r.nextInt(5);assertEquals(expected.keySet().stream().anyMatch(w->w.startsWith(prefix)),actual.startsWith(prefix));}}String prefix="book1";List<String> baseline=expected.entrySet().stream().filter(e->e.getKey().startsWith(prefix)).sorted(Map.Entry.<String,Integer>comparingByValue().reversed().thenComparing(Map.Entry.comparingByKey())).limit(20).map(Map.Entry::getKey).toList();assertEquals(baseline,actual.topK(prefix,20));}
 @Test void lruEvictsLeastRecentlyUsed(){LruCache<Integer,String> c=new LruCache<>(2);c.put(1,"a");c.put(2,"b");assertEquals("a",c.get(1));c.put(3,"c");assertNull(c.get(2));assertEquals(2,c.size());}
 @Test void lruMatchesLinkedHashMapAcrossRandomOperations(){int capacity=32;LruCache<Integer,Integer> actual=new LruCache<>(capacity);LinkedHashMap<Integer,Integer> baseline=new LinkedHashMap<>(64,.75f,true);Random r=new Random(108);for(int i=0;i<100_000;i++){int key=r.nextInt(80);if(r.nextInt(3)==0)assertEquals(baseline.get(key),actual.get(key));else{int value=r.nextInt();actual.put(key,value);baseline.put(key,value);if(baseline.size()>capacity)baseline.remove(baseline.keySet().iterator().next());}assertEquals(baseline.size(),actual.size());}}
}
